#include <iostream>
#include <fstream>
using namespace std;

struct Pt { int x, y; };

int cross(Pt a, Pt b, Pt p) {
    return (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
}

int main() {
    ifstream plik("dane.txt");
    Pt A, B, C;
    plik >> A.x >> A.y >> B.x >> B.y >> C.x >> C.y;
    int n;
    plik >> n;
    cout << "Trojkat: (" << A.x << "," << A.y << ")(" << B.x << "," << B.y << ")(" << C.x << "," << C.y << ")" << endl;
    for (int i = 0; i < n; i++) {
        Pt P;
        plik >> P.x >> P.y;
        int c1 = cross(A, B, P);
        int c2 = cross(B, C, P);
        int c3 = cross(C, A, P);
        cout << "(" << P.x << "," << P.y << "): ";
        if (c1 == 0 || c2 == 0 || c3 == 0) {
            bool allNonNeg = (c1 >= 0 && c2 >= 0 && c3 >= 0);
            bool allNonPos = (c1 <= 0 && c2 <= 0 && c3 <= 0);
            if (allNonNeg || allNonPos)
                cout << "NA BRZEGU" << endl;
            else
                cout << "NA ZEWNATRZ" << endl;
        } else {
            bool allPos = (c1 > 0 && c2 > 0 && c3 > 0);
            bool allNeg = (c1 < 0 && c2 < 0 && c3 < 0);
            if (allPos || allNeg)
                cout << "WEWNATRZ" << endl;
            else
                cout << "NA ZEWNATRZ" << endl;
        }
    }
    return 0;
}
```

**Wyjasnienie**: Punkt lezy wewnatrz trojkata gdy iloczyny wektorowe dla kazdego boku maja ten sam znak (punkt po tej samej stronie kazdego boku). Jesli iloczyn = 0, punkt lezy na prostej zawierajacej bok.

